const COMMENT_BEGIN = new RegExp("/\\*", "uy");
const COMMENT_END = new RegExp("\\*/", "gu");
const STRING_BEGIN = new RegExp("\"", "uy");
// A string's end (group 1) or an escape, whichever comes first, the end on a
// tie, as TextMate tries a begin/end rule's end first. One search, not two:
// searching each to the end of the line per escape was quadratic.
const STRING_NEXT = new RegExp("(\")|%[0-9A-Fa-f]{2}", "gu");
const WORD = new RegExp("[\\p{Alpha}\\p{M}\\p{Decimal_Number}\\p{Pc}\\u00b2\\u00b3\\u00b9\\u00bc-\\u00be]+", "uy");

// CodeMirror's stream parser stops asking for tokens once one starts past this
// many characters into a line (C.MaxLineLength in @codemirror/language).
const MAX_LINE_LENGTH = 10000;

/** The first match of global `regex` in `text` at or after `from`, or null. */
function search(regex, text, from) {
  regex.lastIndex = from;
  return regex.exec(text);
}

/** The length of sticky `regex`'s match in `text` at `from`, or -1. */
function at(regex, text, from) {
  regex.lastIndex = from;
  const match = regex.exec(text);
  return match ? match[0].length : -1;
}

/** The relevance tokenizer: the line's next token, from `state`. */
function step(stream, state) {
  const text = stream.string;
  if (state.inside === "comment") {
    const end = search(COMMENT_END, text, stream.pos);
    if (end) {
      stream.pos = end.index + end[0].length;
      state.inside = null;
    } else stream.skipToEnd();
    return "blockComment";
  }
  if (state.inside === "string") {
    const next = search(STRING_NEXT, text, stream.pos);
    if (next && next.index === stream.pos) {
      stream.pos += next[0].length;
      if (next[1] !== undefined) {
        state.inside = null;
        return "string";
      }
      return "escape";
    }
    if (next) stream.pos = next.index;
    else stream.skipToEnd();
    return "string";
  }
  if (stream.eatSpace()) return null;
  let length = at(COMMENT_BEGIN, text, stream.pos);
  if (length >= 0) {
    stream.pos += length;
    state.inside = "comment";
    return "blockComment";
  }
  length = at(STRING_BEGIN, text, stream.pos);
  if (length >= 0) {
    stream.pos += length;
    state.inside = "string";
    return "string";
  }
  for (const [name, regex] of RULES) {
    length = at(regex, text, stream.pos);
    if (length > 0) {
      stream.pos += length;
      return name;
    }
  }
  // Nothing starts here. No rule can start inside a run of word characters
  // (each word rule begins at a word boundary), so skip the whole run.
  length = at(WORD, text, stream.pos);
  stream.pos += length > 0 ? length : 1;
  return null;
}

function token(stream, state) {
  if (stream.pos > MAX_LINE_LENGTH) {
    // CodeMirror asks for no more tokens on this line after this one, and the
    // rest goes uncolored. Read it anyway, so a comment or string that opens
    // or closes past the cut leaves the next line in the right state.
    while (!stream.eol()) step(stream, state);
    return null;
  }
  return step(stream, state);
}

/** The relevance language: a StreamLanguage, an extension in its own right. */
export function relevanceLanguage(CM) {
  const missing = REQUIRED_CM.filter((name) => !(name in CM));
  if (missing.length) throw new Error(`relevanceLanguage: CM lacks ${missing.join(", ")}`);
  return CM.StreamLanguage.define({
    name: "bigfix-relevance",
    startState: () => ({ inside: null }),
    copyState: (state) => ({ inside: state.inside }),
    token,
    languageData: { commentTokens: { block: { open: "/*", close: "*/" } } },
  });
}
